    // mid is in [c, f], and by precondition c >= 0 when the interval is non-empty.
    let mid_usize = mid as usize;
    let mid_val = v[mid_usize];

    if mid_val <= elem {
        // mid qualifies, so the last <= elem is in [mid+1, f] or at mid.
        binary_search_recursive(v, elem, mid + 1, f)
    } else {
        // mid is too large, so the last <= elem is in [c, mid-1].
        binary_search_recursive(v, elem, c, mid - 1)
    }
